<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;
class ExecutiveDirective extends Model { protected $fillable=['title','directive','responsible_team','issued_on','due_on','scheduled_for','reschedule_reason','rescheduled_by','rescheduled_at','status','progress','latest_feedback','feedback_at','directed_by','tracked_by','assigned_to','recipient_scope','forwarded_by','forwarded_at','acknowledged_at','completed_at']; protected function casts():array{return ['issued_on'=>'date','due_on'=>'date','scheduled_for'=>'datetime','rescheduled_at'=>'datetime','feedback_at'=>'datetime','forwarded_at'=>'datetime','acknowledged_at'=>'datetime','completed_at'=>'datetime'];} public function director(){return $this->belongsTo(User::class,'directed_by');} public function tracker(){return $this->belongsTo(User::class,'tracked_by');} public function assignee(){return $this->belongsTo(User::class,'assigned_to');} public function forwarder(){return $this->belongsTo(User::class,'forwarded_by');} public function rescheduler(){return $this->belongsTo(User::class,'rescheduled_by');} }
